message.content:
{
  "description": "The creature is shown in right-facing side profile standing on a small patch of bare dirt with sparse pebbles and tufts of moss. It has a stout, low-slung body with a pale pink, wrinkled and transversely ringed underbelly and sides, and a broad back and long thick tail covered dorsally in overlapping glossy brown scales. The head at the front right is rounded, pale pink and smooth with large prominent eyes, a blunt snout with small nostrils, and a faint smile, with six feathery pink external gills protruding from behind the head. It stands on four short thick limbs with clawed feet, and the tail tapers to a point at the left rear.",
  "parts": [
    {
      "part": "head",
      "looks_like": "rounded, pale pink and fleshy with smooth skin, blunt snout, small pink nostrils, slightly upturned mouth, and scattered small dark speckles on the crown",
      "where": "at the front right end of the body, facing right"
    },
    {
      "part": "eyes",
      "looks_like": "large, round and glossy with big black pupils surrounded by a pale blue iris ring",
      "where": "on the sides of the head, one clearly visible on the right side"
    },
    {
      "part": "gills",
      "looks_like": "six feathery, branching pink external gills with fine filamentous frills, three stalks on each side of the head",
      "where": "protruding outward from just behind the head on both left and right sides, the right side more visible"
    },
    {
      "part": "scales",
      "looks_like": "large, overlapping, rounded keratinous scales in glossy brown with darker brown edges and lighter centers, arranged in diagonal rows like armor",
      "where": "covering the entire dorsal surface from the base of the gills over the back and continuing down the top and sides of the tail"
    },
    {
      "part": "legs",
      "looks_like": "four short, thick, pale pink limbs with wrinkled, fleshy skin and visible folds at the joints",
      "where": "two forelegs under the chest and two hindlegs under the rear belly, supporting the body above the ground"
    },
    {
      "part": "feet",
      "looks_like": "broad, five-toed feet with short dark claws at the tip of each toe, splayed flat",
      "where": "at the distal end of each of the four legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, thick and tapering, dorsally covered in the same brown overlapping scales and ventrally pale pink with transverse wrinkles and rings, ending in a blunt point",
      "where": "extending from the rear of the body to the left side of the image"
    },
    {
      "part": "skin/markings",
      "looks_like": "pale pink, soft and wrinkled with transverse ring-like folds along the belly, sides, limbs and underside of tail, with small dark speckles on the top of the head",
      "where": "on all exposed flesh not covered by scales: underbelly, sides of body, limbs, tail underside, and head"
    }
  ],
  "attached_objects": [],
  "animals": ["axolotl", "pangolin"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
